import{_ as l,o as t,c as p,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"Dell @ Ceph Day London","description":"","frontmatter":{"title":"Dell @ Ceph Day London","date":"2014-12-22T00:00:00.000Z","updated":"2014-12-22T00:00:00.000Z","tags":["Dell","Ceph","分布式存储","OpenStack","存储解决方案"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/Dell_@_Ceph_Day_London.md","filePath":"posts/2014/Dell_@_Ceph_Day_London.md","lastUpdated":1780459816000}'),o={name:"posts/2014/Dell_@_Ceph_Day_London.md"};function a(i,e,s,r,_,h){return t(),p("div",null,[...e[0]||(e[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Dell 对 Red Hat OpenStack 的赞助及 Ceph 存储解决方案的讨论</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Paul（Dell 代表）、Steve Smith（HPC 业务负责人）、Ross（主持人）</p><p><strong>会议内容</strong>：</p><p><strong>一、Dell 对 Red Hat OpenStack 的赞助</strong></p><ul><li>Dell 认识到 OpenStack 在存储领域的潜力，并希望通过赞助活动推广 OpenStack。</li><li>Dell 认为OpenStack 允许客户以更低的成本实现更多功能，符合 Dell 的业务理念。</li><li>Dell 通过赞助活动，利用其渠道合作伙伴和销售团队的力量，推广 OpenStack 及其存储解决方案。</li></ul><p><strong>二、Ceph 存储解决方案</strong></p><ul><li>Dell 强调 Ceph 作为 OpenStack 的一部分，在存储领域的重要性。</li><li>Steve Smith 从 HPC 业务的角度，分享了 Ceph 在高性能计算领域的应用。</li><li><strong>关键议题</strong>： <ul><li>明确业务目标和系统规模，包括存储容量、IOPS、吞吐量等。</li><li>考虑数据冗余、可靠性、可扩展性等因素，选择合适的硬件和软件配置。</li><li>优化硬件配置，推荐使用 Intel Xeon E5-2620/2630/2640 V3 处理器、64GB 内存、近线 SAS 硬盘等。</li><li>配置网络，前端网络使用 10G 网络，后端网络需要至少 10G 网络，并支持 40G 或 100G 网络。</li><li>使用 Ceph 存储软件，并注意配置文件和参数优化。</li></ul></li></ul><p><strong>三、挑战与机遇</strong></p><ul><li>会议讨论了 Ceph 存储在数据存储、安全、可靠性等方面的挑战。</li><li>Dell 强调 Ceph 具备应对这些挑战的能力，并鼓励客户尽早部署 Ceph。</li></ul><p><strong>四、行动计划</strong></p><ul><li>Dell 将继续推广 Ceph 存储解决方案，并提供相关培训和支持。</li><li>Dell 将与 Inktank 合作，共同推动 Ceph 生态系统的建设。</li></ul><p><strong>五、其他</strong></p><ul><li>会议还讨论了 Ceph 在研究数据存储中的应用、Ceph 与其他存储解决方案的比较以及 Ceph 的未来发展趋势。</li></ul><p><strong>总结</strong>：</p><p>本次会议深入讨论了 Ceph 存储解决方案，并分享了 Dell 的相关经验。会议强调了 Ceph 在存储领域的重要性和潜力，并鼓励客户尽早部署 Ceph。</p>',17)])])}const D=l(o,[["render",a]]);export{C as __pageData,D as default};
